-- SkyCRM users, one per SamvadX person (2026-11-05). SkyCRM (Ravindra) wants every person who
-- calls to exist as a user in their system, so they can count users. SamvadX creates them through
-- SkyCRM's users_webhook_api (Superadmin → company → Telephony → "Create SkyCRM users").
--
-- The password is generated by SamvadX and kept here because SamvadX — not the person — will log
-- the user in to SkyCRM (login API: username + password + extension). Nobody types it anywhere.
-- Server-only: RLS on, no policies, no grant to authenticated.
--
-- check:sql server-only: skycrm_users

CREATE TABLE IF NOT EXISTS skycrm_users (
  agent_id     UUID PRIMARY KEY REFERENCES agents(id) ON DELETE CASCADE,
  client_id    UUID NOT NULL REFERENCES clients(id) ON DELETE CASCADE,
  username     TEXT NOT NULL,
  password     TEXT NOT NULL,
  -- admin | manager | user (SkyCRM's names; they store 10 / 9 / 1)
  user_level   TEXT NOT NULL,
  -- created: SkyCRM answered success · failed: it didn't (last_error says why; retried on next click)
  status       TEXT NOT NULL CHECK (status IN ('created', 'failed')),
  last_error   TEXT,
  created_at   TIMESTAMPTZ,
  attempted_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- A SkyCRM username exists once in SkyCRM, across every company.
CREATE UNIQUE INDEX IF NOT EXISTS skycrm_users_username_idx ON skycrm_users (lower(username));
CREATE INDEX IF NOT EXISTS skycrm_users_client_idx ON skycrm_users (client_id);

ALTER TABLE skycrm_users ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE skycrm_users FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE skycrm_users TO service_role;
